```
BFS from (0,0):
  mark (0,0) visited, enqueue
  while queue not empty:
    pop (x,y)
    if (x,y) == (m-1, n-1): return true
    for each direction d allowed by grid[x][y]:
      (nx,ny) = neighbor in direction d
      if in bounds and not visited:
        if grid[nx][ny] allows opposite(d):
          mark visited, enqueue
  return false
```

code.cpp:
class Solution {
public:
    bool hasValidPath(vector<vector<int>>& grid) {
        int m = grid.size();
        int n = grid[0].size();

        // Directions: 0=left, 1=right, 2=up, 3=down
        int dx[] = {0, 0, -1, 1};
        int dy[] = {-1, 1, 0, 0};

        // For each street type, which directions are allowed
        vector<vector<int>> allowed(7);
        allowed[1] = {0, 1};  // left, right
        allowed[2] = {2, 3};  // up, down
        allowed[3] = {0, 3};  // left, down
        allowed[4] = {1, 3};  // right, down
        allowed[5] = {0, 2};  // left, up
        allowed[6] = {1, 2};  // right, up

        // Opposite direction: left<->right, up<->down
        int opp[] = {1, 0, 3, 2};

        vector<vector<bool>> visited(m, vector<bool>(n, false));
        queue<pair<int,int>> q;
        q.push({0, 0});
        visited[0][0] = true;

        while (!q.empty()) {
            auto [x, y] = q.front();
            q.pop();
            if (x == m - 1 && y == n - 1) return true;

            int type = grid[x][y];
            for (int d : allowed[type]) {
                int nx = x + dx[d];
                int ny = y + dy[d];
                if (nx < 0 || nx >= m || ny < 0 || ny >= n) continue;
                if (visited[nx][ny]) continue;
                int ntype = grid[nx][ny];
                bool canConnect = false;
                for (int nd : allowed[ntype]) {
                    if (nd == opp[d]) {
                        canConnect = true;
                        break;
                    }
                }
                if (canConnect) {
                    visited[nx][ny] = true;
                    q.push({nx, ny});
                }
            }
        }
        return false;
    }
};
